"""Self-contained offline review UI; user data never becomes HTML markup."""
import json

TEMPLATE = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Qazaq Loc QA · Review desk</title>
<style>
:root{color-scheme:dark;--bg:#0b101b;--panel:#141d2d;--line:#293952;--ink:#e8edf7;--muted:#a5b2c8;--mint:#75e0be}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,sans-serif}header,main{max-width:1180px;margin:auto;padding:28px}header{padding-bottom:12px}.brand{color:var(--mint);font-size:12px;letter-spacing:2px}h1{font-size:36px;line-height:1.1;margin:14px 0}p{color:var(--muted)}.metrics{display:flex;gap:12px;flex-wrap:wrap}.metric{background:var(--panel);border:1px solid var(--line);padding:14px 22px;border-radius:12px}.metric strong{font-size:24px;display:block}.toolbar{display:flex;gap:12px;flex-wrap:wrap;position:sticky;top:0;background:var(--bg);padding:16px 0;z-index:2}input,select,textarea,button{font:inherit;border:1px solid var(--line);border-radius:8px;padding:10px;background:#0d1625;color:var(--ink)}input[type=search]{flex:1;min-width:180px}button{background:var(--mint);color:#092019;font-weight:700;cursor:pointer}button:disabled{opacity:.4;cursor:default}.card{padding:22px;margin:14px 0;background:var(--panel);border:1px solid var(--line);border-radius:12px}.card h2{font:600 16px/1.4 ui-monospace,monospace;word-break:break-word;margin-top:0}.tag{display:inline-block;border:1px solid var(--line);border-radius:20px;font-size:12px;padding:3px 9px;margin:0 5px 6px 0}.high{color:#ffadab}.medium{color:#ffda96}.low{color:#a9c6ff}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.text{white-space:pre-wrap;overflow-wrap:anywhere}.label{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:1px}textarea{display:block;width:100%;min-height:75px;resize:vertical;margin:6px 0 12px}.evidence{font-size:13px;color:var(--muted);margin-bottom:12px}label{cursor:pointer}.notice{border-left:3px solid var(--mint);padding:8px 16px}.small{font-size:12px}a{color:var(--mint)}@media(max-width:650px){.pair{grid-template-columns:1fr}header,main{padding:16px}h1{font-size:28px}}
</style>
<header><div class="brand">QAZAQ LOC QA / EVIDENCE FIRST</div><h1>Localization review desk</h1><p>Inspect the evidence. Edit the proposed translation. Confirm only after a human has checked meaning, context and Kazakh grammar.</p><div class="metrics" id="metrics"></div><p class="notice" id="notice"></p></header>
<main><div class="toolbar"><input type="search" id="search" aria-label="Search findings" placeholder="Search keys, text, evidence…"><select id="type" aria-label="Issue type"><option value="">All issue types</option></select><select id="severity" aria-label="Severity"><option value="">All severities</option><option>high</option><option>medium</option><option>low</option></select></div><div class="toolbar"><input id="reviewer" placeholder="Human reviewer name / ID" aria-label="Reviewer name"><button id="export">Export human review manifest</button><span id="count"></span></div><p class="small">Edits live in this page until exported. Export before closing. The exported manifest is applied with <code>locqa apply</code>; this page never changes your ARB.</p><div id="cards"></div></main>
<script id="payload" type="application/json">__PAYLOAD__</script>
<script>
'use strict';
const data=JSON.parse(document.getElementById('payload').textContent), groups=new Map(), states=new Map();
for(const issue of data.issues){if(!groups.has(issue.key))groups.set(issue.key,[]);groups.get(issue.key).push(issue)}
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
for(const [label,value] of [['Findings',data.issues.length],['Keys to inspect',groups.size],['Human confirmed',0]]){const box=el('div',undefined,'metric');box.append(el('strong',String(value)),el('span',label));document.getElementById('metrics').append(box)}
document.getElementById('notice').textContent=data.label+' · '+data.total+' source messages · Evidence-based audit. Length warnings estimate risk; no rendered UI measurements. Human verification starts at zero.';
for(const t of [...new Set(data.issues.map(i=>i.issue_type))].sort()){const o=el('option',t);o.value=t;document.getElementById('type').append(o)}
function count(){const n=[...states.values()].filter(s=>s.checked).length;document.querySelectorAll('.metric strong')[2].textContent=n;document.getElementById('count').textContent=n+' confirmed rows'}
for(const [key,items] of groups){const first=items[0], card=el('article',undefined,'card');card.append(el('h2',key));for(const i of items){card.append(el('span',i.severity+' · '+i.issue_type+' · '+i.confidence.toFixed(2),'tag '+i.severity),el('div',i.evidence,'evidence'))}const pair=el('div',undefined,'pair');for(const [label,text] of [['Russian source',first.source],['Current target',first.target]]){const box=el('div');box.append(el('div',label,'label'),el('div',text,'text'));pair.append(box)}card.append(pair);const area=el('textarea');area.setAttribute('aria-label','Translation for '+key);area.value=(Object.hasOwn(data.proposals,key)?data.proposals[key]:null)||items.find(i=>i.suggestion)?.suggestion||first.target;card.append(el('div','Proposed translation — editable','label'),area);const label=el('label'),cb=el('input');cb.type='checkbox';label.append(cb,document.createTextNode(' I personally checked this translation and these findings.'));card.append(label);states.set(key,{text:area.value,checked:false});area.addEventListener('input',()=>{states.get(key).text=area.value;states.get(key).checked=false;cb.checked=false;count()});cb.addEventListener('change',()=>{states.get(key).checked=cb.checked;count()});card.dataset.key=key;document.getElementById('cards').append(card)}
function filter(){let shown=0;const q=document.getElementById('search').value.toLocaleLowerCase(),t=document.getElementById('type').value,s=document.getElementById('severity').value;for(const card of document.querySelectorAll('.card')){const items=groups.get(card.dataset.key);const ok=items.some(i=>(!t||i.issue_type===t)&&(!s||i.severity===s)&&(!q||JSON.stringify(i).toLocaleLowerCase().includes(q)));card.hidden=!ok;if(ok)shown++}document.getElementById('count').textContent=shown+' visible keys'}
for(const id of ['search','type','severity'])document.getElementById(id).addEventListener('input',filter);
document.getElementById('export').addEventListener('click',()=>{const reviewer=document.getElementById('reviewer').value.trim();if(!reviewer){alert('Enter the actual human reviewer identity first.');return}const entries=[];for(const [key,state] of states){if(state.checked){const f=groups.get(key)[0];entries.push({key,source:f.source,original:f.target,translation:state.text,reviewed_by_human:true,reviewer,reviewed_at:new Date().toISOString(),issue_types:groups.get(key).map(i=>i.issue_type)})}}if(!entries.length){alert('No human-confirmed rows selected.');return}const manifest={version:1,source_sha256:data.source_sha256,target_sha256:data.target_sha256,entries};const blob=new Blob([JSON.stringify(manifest,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='human_reviews.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
</script></html>'''

def render(issues, source_hash, target_hash, total, proposals=None, label='User-provided ARB'):
    payload=json.dumps(dict(issues=issues,source_sha256=source_hash,target_sha256=target_hash,total=total,proposals=proposals or {},label=label),ensure_ascii=False)
    # Prevent raw ARB content (including </script>) from escaping the data block.
    payload=payload.replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
    return TEMPLATE.replace('__PAYLOAD__',payload)
